function mergeTwoLists(l1, l2) {
  const dummy = new ListNode(0);
  let curr = dummy;
  while (l1 && l2) {
    if (l1.val <= l2.val) { curr.next = l1; l1 = l1.next; }
    else { curr.next = l2; l2 = l2.next; }
    curr = curr.next;
  }
  curr.next = l1 || l2;
  return dummy.next;
}

function maxProfit(prices) {
  let min = Infinity, max = 0;
  for (const p of prices) {
    if (p < min) min = p;
    else if (p - min > max) max = p - min;
  }
  return max;
}

function isPalindrome(s) {
  let l = 0, r = s.length - 1;
  while (l < r) {
    while (l < r && !/^[a-z0-9]$/i.test(s[l])) l++;
    while (l < r && !/^[a-z0-9]$/i.test(s[r])) r--;
    if (s[l++].toLowerCase() !== s[r--].toLowerCase()) return false;
  }
  return true;
}

function hasCycle(head) {
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow.next;
    fast = fast.next.next;
    if (slow === fast) return true;
  }
  return false;
}

function productExceptSelf(nums) {
  const n = nums.length;
  const ans = new Array(n).fill(1);
  let left = 1, right = 1;
  for (let i = 0; i < n; i++) {
    ans[i] *= left;
    left *= nums[i];
    ans[n - 1 - i] *= right;
    right *= nums[n - 1 - i];
  }
  return ans;
}

function lengthOfLongestSubstring(s) {
  const set = new Set();
  let l = 0, max = 0;
  for (let r = 0; r < s.length; r++) {
    while (set.has(s[r])) set.delete(s[l++]);
    set.add(s[r]);
    max = Math.max(max, r - l + 1);
  }
  return max;
}

function threeSum(nums) {
  nums.sort((a, b) => a - b);
  const res = [];
  for (let i = 0; i < nums.length - 2; i++) {
    if (i > 0 && nums[i] === nums[i - 1]) continue;
    let l = i + 1, r = nums.length - 1;
    while (l < r) {
      const sum = nums[i] + nums[l] + nums[r];
      if (!sum) {
        res.push([nums[i], nums[l], nums[r]]);
        while (l < r && nums[l] === nums[l + 1]) l++;
        while (l < r && nums[r] === nums[r - 1]) r--;
        l++; r--;
      } else if (sum < 0) l++;
      else r--;
    }
  }
  return res;
}

function mergeKLists(lists) {
  if (!lists.length) return null;
  const mergeTwo = (a, b) => {
    const dummy = new ListNode(0);
    let curr = dummy;
    while (a && b) {
      if (a.val <= b.val) { curr.next = a; a = a.next; }
      else { curr.next = b; b = b.next; }
      curr = curr.next;
    }
    curr.next = a || b;
    return dummy.next;
  };
  let interval = 1;
  while (interval < lists.length) {
    for (let i = 0; i < lists.length - interval; i += interval * 2) {
      lists[i] = mergeTwo(lists[i], lists[i + interval]);
    }
    interval *= 2;
  }
  return lists[0];
}

function maxSubArray(nums) {
  let max = nums[0], curr = nums[0];
  for (let i = 1; i < nums.length; i++) {
    curr = Math.max(nums[i], curr + nums[i]);
    max = Math.max(max, curr);
  }
  return max;
}

function maxProduct(nums) {
  let max = nums[0], min = nums[0], ans = nums[0];
  for (let i = 1; i < nums.length; i++) {
    const tmpMax = max;
    max = Math.max(nums[i], max * nums[i], min * nums[i]);
    min = Math.min(nums[i], tmpMax * nums[i], min * nums[i]);
    ans = Math.max(ans, max);
  }
  return ans;
}

function maxArea(height) {
  let l = 0, r = height.length - 1, max = 0;
  while (l < r) {
    max = Math.max(max, Math.min(height[l], height[r]) * (r - l));
    if (height[l] < height[r]) l++;
    else r--;
  }
  return max;
}

function groupAnagrams(strs) {
  const map = new Map();
  for (const s of strs) {
    const key = s.split('').sort().join('');
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(s);
  }
  return [...map.values()];
}

function setZeroes(matrix) {
  const m = matrix.length, n = matrix[0].length;
  let firstRowHasZero = false, firstColHasZero = false;
  for (let j = 0; j < n; j++) if (!matrix[0][j]) firstRowHasZero = true;
  for (let i = 0; i < m; i++) if (!matrix[i][0]) firstColHasZero = true;
  for (let i = 1; i < m; i++)
    for (let j = 1; j < n; j++)
      if (!matrix[i][j]) { matrix[i][0] = 0; matrix[0][j] = 0; }
  for (let i = 1; i < m; i++)
    for (let j = 1; j < n; j++)
      if (!matrix[i][0] || !matrix[0][j]) matrix[i][j] = 0;
  if (firstRowHasZero) for (let j = 0; j < n; j++) matrix[0][j] = 0;
  if (firstColHasZero) for (let i = 0; i < m; i++) matrix[i][0] = 0;
}
